	entry2 := &CacheEntry{
		Body:       []byte(`{"message":"test2"}`),
		StatusCode: 200,
		Headers:    http.Header{},
		CreatedAt:  time.Now(),
	}
	cache.Set("key2", entry2, 1*time.Minute)

	time.Sleep(10 * time.Millisecond)

	entry3 := &CacheEntry{
		Body:       []byte(`{"message":"test3"}`),
		StatusCode: 200,
		Headers:    http.Header{},
		CreatedAt:  time.Now(),
	}
	cache.Set("key3", entry3, 1*time.Minute) // Should evict key1 (oldest)

	stats := cache.Stats()
	if stats.Size != 2 {
