package axios4go

import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Cache defines the interface for cache implementations.
// Users can implement this interface for custom storage backends (Redis, file, etc.)
type Cache interface {
	// Get retrieves a cached response by key. Returns nil if not found or expired.
	Get(key string) *CacheEntry

	// Set stores a response in the cache with the given key and TTL.
	Set(key string, entry *CacheEntry, ttl time.Duration)

	// Delete removes an entry from the cache.
	Delete(key string)

	// Clear removes all entries from the cache.
	Clear()

	// Stats returns cache statistics.
	Stats() CacheStats
}

// CacheEntry represents a cached HTTP response
type CacheEntry struct {
	Body       []byte
	StatusCode int
	Headers    http.Header
	CreatedAt  time.Time
	ExpiresAt  time.Time
}

// IsExpired checks if the cache entry has expired
func (e *CacheEntry) IsExpired() bool {
	return time.Now().After(e.ExpiresAt)
}

// CacheStats provides cache statistics
type CacheStats struct {
	Hits   int64
	Misses int64
	Size   int64
}

// CacheKeyFunc is a function type for generating cache keys. headers holds the
// final outgoing request headers, including any added by request interceptors
// and the Authorization header derived from RequestOptions.Auth. When the
// request has a body, a hash of the body is appended to the returned key.
type CacheKeyFunc func(method, fullURL string, headers map[string]string) string

// CacheConfig holds the global cache configuration for a Client
type CacheConfig struct {
	// Cache is the cache implementation to use
	Cache Cache

	// DefaultTTL is the default TTL for cached responses when per-request TTL is not specified
	// A value of 0 means no default TTL (must be specified per-request)
	DefaultTTL time.Duration

	// KeyFunc is a custom function to generate cache keys
	// If nil, DefaultCacheKeyFunc (Method + URL + hashed headers) is used
	KeyFunc CacheKeyFunc

	// CacheableMethods defines which HTTP methods can be cached
	// If nil, defaults to []string{"GET"}
	CacheableMethods []string
}

// RequestCacheOptions holds per-request cache configuration
type RequestCacheOptions struct {
	// Enabled explicitly enables/disables caching for this request
	// If nil, caching is disabled (opt-in model)
	Enabled *bool

	// TTL sets the TTL for this specific request
	// Overrides the global DefaultTTL if set
	TTL time.Duration

	// ForceRefresh bypasses the cache and fetches fresh data
	// The fresh response will still be cached
	ForceRefresh bool

	// CustomKey allows overriding the cache key for this request
	CustomKey string
}

// Bool is a helper function to create a pointer to a bool value
func Bool(v bool) *bool {
	return &v
}

// CacheEnabled returns a RequestCacheOptions with caching enabled
func CacheEnabled(ttl time.Duration) *RequestCacheOptions {
	enabled := true
	return &RequestCacheOptions{
		Enabled: &enabled,
		TTL:     ttl,
	}
}

// CacheDisabled returns a RequestCacheOptions with caching disabled
func CacheDisabled() *RequestCacheOptions {
	enabled := false
	return &RequestCacheOptions{
		Enabled: &enabled,
	}
}

// DefaultCacheKeyFunc generates a cache key from method, full URL and the
// request headers. Headers are folded into a single SHA-256 digest so any
// header that may select a different representation, such as Authorization,
// Cookie or a custom API key header, varies the key without the values
// themselves ever appearing in the key.
func DefaultCacheKeyFunc(method, fullURL string, headers map[string]string) string {
	key := strings.ToUpper(method) + ":" + fullURL
	if len(headers) == 0 {
		return key
	}
	pairs := make([]string, 0, len(headers))
	for name, value := range headers {
		pairs = append(pairs, strings.ToLower(name)+"="+value)
	}
	sort.Strings(pairs)
	sum := sha256.Sum256([]byte(strings.Join(pairs, "\n")))
	return key + ":h=" + hex.EncodeToString(sum[:])
}

// MemoryCache is a thread-safe in-memory cache implementation
type MemoryCache struct {
	// hits and misses use atomic.Int64, which guarantees the 8-byte
	// alignment that 32-bit platforms require for atomic access.
	hits            atomic.Int64
	misses          atomic.Int64
	entries         map[string]*memoryCacheEntry
	mu              sync.RWMutex
	maxSize         int
	cleanupInterval time.Duration
	stopChan        chan struct{}
	stopped         bool
}

type memoryCacheEntry struct {
	entry *CacheEntry
}

// MemoryCacheOptions configures the MemoryCache
type MemoryCacheOptions struct {
	// MaxSize is the maximum number of entries (0 = unlimited)
	MaxSize int

	// CleanupInterval is how often to clean expired entries (default: 5 minutes)
	CleanupInterval time.Duration
}

// NewMemoryCache creates a new in-memory cache
func NewMemoryCache(opts *MemoryCacheOptions) *MemoryCache {
	if opts == nil {
		opts = &MemoryCacheOptions{}
	}

	cleanupInterval := opts.CleanupInterval
	if cleanupInterval == 0 {
		cleanupInterval = 5 * time.Minute
	}

	mc := &MemoryCache{
		entries:         make(map[string]*memoryCacheEntry),
		maxSize:         opts.MaxSize,
		cleanupInterval: cleanupInterval,
		stopChan:        make(chan struct{}),
	}

	// Start background cleanup goroutine
	go mc.cleanupLoop()

	return mc
}

// Get retrieves a cached response by key
func (c *MemoryCache) Get(key string) *CacheEntry {
	c.mu.RLock()
	entry, exists := c.entries[key]
	if !exists {
		c.mu.RUnlock()
		c.misses.Add(1)
		return nil
	}

	// Copy the entry while holding the lock to avoid race conditions
	entryCopy := cloneCacheEntry(entry.entry)
	c.mu.RUnlock()

	if entryCopy.IsExpired() {
		// Delete expired entry
		c.Delete(key)
		c.misses.Add(1)
		return nil
	}

	c.hits.Add(1)
	return entryCopy
}

// Set stores a response in the cache
func (c *MemoryCache) Set(key string, entry *CacheEntry, ttl time.Duration) {
	if entry == nil || ttl <= 0 {
		return
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Check max size and evict oldest if necessary
	if c.maxSize > 0 && len(c.entries) >= c.maxSize {
		// Simple eviction: remove first expired or oldest entry
		c.evictOne()
	}

	entry = cloneCacheEntry(entry)
	entry.ExpiresAt = time.Now().Add(ttl)
	c.entries[key] = &memoryCacheEntry{
		entry: entry,
	}
}

func cloneCacheEntry(entry *CacheEntry) *CacheEntry {
	if entry == nil {
		return nil
	}
	return &CacheEntry{
		Body:       append([]byte(nil), entry.Body...),
		StatusCode: entry.StatusCode,
		Headers:    entry.Headers.Clone(),
		CreatedAt:  entry.CreatedAt,
		ExpiresAt:  entry.ExpiresAt,
	}
}

// Delete removes an entry from the cache
func (c *MemoryCache) Delete(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.entries, key)
}

// Clear removes all entries from the cache
func (c *MemoryCache) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.entries = make(map[string]*memoryCacheEntry)
}

// Stats returns cache statistics
func (c *MemoryCache) Stats() CacheStats {
	c.mu.RLock()
	size := int64(len(c.entries))
	c.mu.RUnlock()

	return CacheStats{
		Hits:   c.hits.Load(),
		Misses: c.misses.Load(),
		Size:   size,
	}
}

// Close stops the background cleanup goroutine
func (c *MemoryCache) Close() {
	c.mu.Lock()
	if !c.stopped {
		c.stopped = true
		close(c.stopChan)
	}
	c.mu.Unlock()
}

// evictOne removes one entry to make room (called with lock held)
func (c *MemoryCache) evictOne() {
	var oldestKey string
	var oldestTime time.Time
	first := true

	for key, entry := range c.entries {
		// First, try to evict expired entries
		if entry.entry.IsExpired() {
			delete(c.entries, key)
			return
		}

		// Track oldest entry
		if first || entry.entry.CreatedAt.Before(oldestTime) {
			oldestKey = key
			oldestTime = entry.entry.CreatedAt
			first = false
		}
	}

	// Evict oldest if no expired entries found
	if oldestKey != "" {
		delete(c.entries, oldestKey)
	}
}

// cleanupLoop runs periodically to remove expired entries
func (c *MemoryCache) cleanupLoop() {
	ticker := time.NewTicker(c.cleanupInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			c.cleanupExpired()
		case <-c.stopChan:
			return
		}
	}
}

// cleanupExpired removes all expired entries
func (c *MemoryCache) cleanupExpired() {
	c.mu.Lock()
	defer c.mu.Unlock()

	for key, entry := range c.entries {
		if entry.entry.IsExpired() {
			delete(c.entries, key)
		}
	}
}

// shouldCacheRequest determines if a request should be cached
func shouldCacheRequest(cacheConfig *CacheConfig, options *RequestOptions) bool {
	// Check if client has cache configured
	if cacheConfig == nil || cacheConfig.Cache == nil {
		return false
	}

	// Check if per-request cache is explicitly disabled
	if options.Cache != nil && options.Cache.Enabled != nil && !*options.Cache.Enabled {
		return false
	}

	// Check if per-request cache is explicitly enabled
	if options.Cache != nil && options.Cache.Enabled != nil && *options.Cache.Enabled {
		return isMethodCacheable(cacheConfig, options.Method)
	}

	// Default: caching is disabled unless explicitly enabled per-request
	return false
}

// isMethodCacheable checks if the HTTP method can be cached
func isMethodCacheable(cacheConfig *CacheConfig, method string) bool {
	methods := cacheConfig.CacheableMethods
	if methods == nil {
		methods = []string{"GET"}
	}
	for _, m := range methods {
		if strings.EqualFold(m, method) {
			return true
		}
	}
	return false
}

// shouldForceRefresh checks if the request should bypass cache
func shouldForceRefresh(options *RequestOptions) bool {
	return options.Cache != nil && options.Cache.ForceRefresh
}

// generateCacheKey generates the cache key for a request. headers are the
// final outgoing request headers and bodyHash is the hex SHA-256 of the
// request body, or empty when there is no body.
func generateCacheKey(cacheConfig *CacheConfig, options *RequestOptions, fullURL string, headers map[string]string, bodyHash string) string {
	// Check for custom key in request options
	if options.Cache != nil && options.Cache.CustomKey != "" {
		return options.Cache.CustomKey
	}

	if headers == nil {
		headers = map[string]string{}
	}

	var key string
	if cacheConfig.KeyFunc != nil {
		key = cacheConfig.KeyFunc(options.Method, fullURL, headers)
	} else {
		key = DefaultCacheKeyFunc(options.Method, fullURL, headers)
	}
	if bodyHash != "" {
		key += ":body=" + bodyHash
	}
	return key
}

// getCacheTTL determines the TTL for a cached response
func getCacheTTL(cacheConfig *CacheConfig, options *RequestOptions) time.Duration {
	// Per-request TTL takes precedence
	if options.Cache != nil && options.Cache.TTL > 0 {
		return options.Cache.TTL
	}

	// Fall back to client default TTL
	return cacheConfig.DefaultTTL
}

package axios4go

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

type LogLevel int

const (
	LevelNone LogLevel = iota
	LevelError
	LevelInfo
	LevelDebug
)

type Logger interface {
	LogRequest(*http.Request, LogLevel)
	LogResponse(*http.Response, []byte, time.Duration, LogLevel)
	LogError(error, LogLevel)
	SetLevel(LogLevel)
}

type LogOptions struct {
	Level          LogLevel
	MaxBodyLength  int
	MaskHeaders    []string
	Output         io.Writer
	TimeFormat     string
	IncludeBody    bool
	IncludeHeaders bool
}

type DefaultLogger struct {
	options LogOptions
}

// DefaultMaskedHeaders are hidden by loggers created with NewLogger.
var DefaultMaskedHeaders = []string{
	"Authorization",
	"Proxy-Authorization",
	"Cookie",
	"Set-Cookie",
	"X-Api-Key",
	"X-Auth-Token",
	"Api-Key",
}

// sanitizeLogValue neutralises CR and LF so a header value cannot forge
// additional log lines.
var logValueSanitizer = strings.NewReplacer("\r", "\\r", "\n", "\\n")

func sanitizeLogValue(v string) string {
	return logValueSanitizer.Replace(v)
}

func NewDefaultLogger(options LogOptions) *DefaultLogger {
	if options.Output == nil {
		options.Output = os.Stdout
	}
	if options.TimeFormat == "" {
		options.TimeFormat = time.RFC3339
	}
	if options.MaxBodyLength == 0 {
		options.MaxBodyLength = 1000
	}
	return &DefaultLogger{options: options}
}

func (l *DefaultLogger) SetLevel(level LogLevel) {
	l.options.Level = level
}

func (l *DefaultLogger) LogRequest(req *http.Request, level LogLevel) {
	if l.options.Level == LevelNone || level == LevelNone || level > l.options.Level {
		return
	}

	var buf strings.Builder
	timestamp := time.Now().Format(l.options.TimeFormat)

	// Redacted hides any password embedded in the URL userinfo.
	fmt.Fprintf(&buf, "[%s] REQUEST: %s %s\n", timestamp, req.Method, req.URL.Redacted())

	if l.options.IncludeHeaders {
		buf.WriteString("Headers:\n")
		for key, vals := range req.Header {
			if l.isHeaderMasked(key) {
				fmt.Fprintf(&buf, "  %s: [MASKED]\n", key)
			} else {
				fmt.Fprintf(&buf, "  %s: %s\n", sanitizeLogValue(key), sanitizeLogValue(strings.Join(vals, ", ")))
			}
		}
	}

	if l.options.IncludeBody && req.Body != nil {
		body, err := io.ReadAll(req.Body)
		if err == nil {
			req.Body = io.NopCloser(bytes.NewBuffer(body))
			if len(body) > l.options.MaxBodyLength {
				fmt.Fprintf(&buf, "Body: (truncated) %s...\n", body[:l.options.MaxBodyLength])
			} else {
				fmt.Fprintf(&buf, "Body: %s\n", body)
			}
		}
	}

	_, _ = fmt.Fprintln(l.options.Output, buf.String())
}

func (l *DefaultLogger) LogResponse(resp *http.Response, body []byte, duration time.Duration, level LogLevel) {
	if l.options.Level == LevelNone || level == LevelNone || level > l.options.Level {
		return
	}

	var buf strings.Builder
	timestamp := time.Now().Format(l.options.TimeFormat)

	fmt.Fprintf(&buf, "[%s] RESPONSE: %d %s (%.2fms)\n",
		timestamp, resp.StatusCode, resp.Status, float64(duration.Microseconds())/1000)

	if l.options.IncludeHeaders {
		buf.WriteString("Headers:\n")
		for key, vals := range resp.Header {
			if l.isHeaderMasked(key) {
				fmt.Fprintf(&buf, "  %s: [MASKED]\n", key)
			} else {
				fmt.Fprintf(&buf, "  %s: %s\n", sanitizeLogValue(key), sanitizeLogValue(strings.Join(vals, ", ")))
			}
		}
	}

	if l.options.IncludeBody && body != nil {
		if len(body) > l.options.MaxBodyLength {
			fmt.Fprintf(&buf, "Body: (truncated) %s...\n", body[:l.options.MaxBodyLength])
		} else {
			fmt.Fprintf(&buf, "Body: %s\n", body)
		}
	}

	_, _ = fmt.Fprintln(l.options.Output, buf.String())
}

func (l *DefaultLogger) LogError(err error, level LogLevel) {
	if l.options.Level == LevelNone || level == LevelNone || level > l.options.Level {
		return
	}

	timestamp := time.Now().Format(l.options.TimeFormat)
	_, _ = fmt.Fprintf(l.options.Output, "[%s] ERROR: %v\n", timestamp, err)
}

func (l *DefaultLogger) isHeaderMasked(header string) bool {
	header = strings.ToLower(header)
	for _, masked := range l.options.MaskHeaders {
		if strings.ToLower(masked) == header {
			return true
		}
	}
	return false
}

func NewLogger(level LogLevel) Logger {
	return NewDefaultLogger(LogOptions{
		Level:          level,
		MaxBodyLength:  1000,
		MaskHeaders:    append([]string(nil), DefaultMaskedHeaders...),
		Output:         os.Stdout,
		TimeFormat:     time.RFC3339,
		IncludeBody:    true,
		IncludeHeaders: true,
	})
}

