}

// safeCall runs fn and converts a panic into an error.
func safeCall(fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("promise callback panicked: %v", r)
		}
	}()
	fn()
	return nil
}

func (p *Promise) Then(fn func(*Response)) *Promise {
	p.mu.Lock()
	if p.settled && p.err == nil {
		response := p.response
		p.mu.Unlock()
		if perr := safeCall(func() { fn(response) }); perr != nil {
			p.mu.Lock()
			p.err = perr
			p.response = nil
			p.mu.Unlock()
		}
	} else {
		if !p.settled {
			p.then = fn
		}
		p.mu.Unlock()
	}
	return p
}

func (p *Promise) Catch(fn func(error)) *Promise {
	p.mu.Lock()
	if p.settled && p.err != nil {
		err := p.err
		p.mu.Unlock()
		fn(err)
	} else {
		if !p.settled {
			p.catch = fn
		}
		p.mu.Unlock()
	}
	return p
}

func (p *Promise) Finally(fn func()) {
	p.mu.Lock()
	if p.settled {
		p.mu.Unlock()
		fn()
	} else {
		p.finally = fn
		p.mu.Unlock()
	}

	<-p.done
}

func NewPromise() *Promise {
	return &Promise{
		done: make(chan struct{}),
	}
}

func (p *Promise) resolve(resp *Response, err error) {
	p.mu.Lock()
	if p.settled {
		p.mu.Unlock()
		return
	}

	p.response = resp
	p.err = err
	p.settled = true
	thenFn := p.then
	catchFn := p.catch
	finallyFn := p.finally
	p.mu.Unlock()

	// Always release Finally waiters, even if a callback panics.
	defer close(p.done)

	if thenFn != nil && err == nil {
		if perr := safeCall(func() { thenFn(resp) }); perr != nil {
			// A panicking Then callback rejects the promise, mirroring a
			// throw inside a JavaScript then handler.
			err = perr
			p.mu.Lock()
			p.err = perr
			p.response = nil
			p.mu.Unlock()
		}
	}
	if catchFn != nil && err != nil {
		catchFn(err)
	}
	if finallyFn != nil {
		finallyFn()
	}
}

