	"time"

	"github.com/rezmoss/axios4go"
)

func main() {
	url := "https://ash-speed.hetzner.com/1GB.bin"
	outputPath := "1GB.bin"

	startTime := time.Now()
	lastPrintTime := startTime

	resp, err := axios4go.Get(url, &axios4go.RequestOptions{
		MaxContentLength: 5 * 1024 * 1024 * 1024, // 5GB
		Timeout:          60000 * 5,
		OnDownloadProgress: func(bytesRead, totalBytes int64) {
			currentTime := time.Now()
			if currentTime.Sub(lastPrintTime) >= time.Second || bytesRead == totalBytes {
				percentage := float64(bytesRead) / float64(totalBytes) * 100
				downloadedMB := float64(bytesRead) / 1024 / 1024
				totalMB := float64(totalBytes) / 1024 / 1024
				elapsedTime := currentTime.Sub(startTime)
				speed := float64(bytesRead) / elapsedTime.Seconds() / 1024 / 1024 // MB/s

				fmt.Printf("\rDownloaded %.2f%% (%.2f MB / %.2f MB) - Speed: %.2f MB/s",
					percentage, downloadedMB, totalMB, speed)

				lastPrintTime = currentTime
			}
		},
	})

	if err != nil {
		fmt.Printf("\nError downloading file: %v\n", err)
		return
	}

	err = writeResponseToFile(resp, outputPath)
	if err != nil {
		fmt.Printf("\nError writing file: %v\n", err)
		return
	}

	fmt.Println("\nDownload completed successfully!!")
}

func writeResponseToFile(resp *axios4go.Response, outputPath string) error {
	return os.WriteFile(outputPath, resp.Body, 0644)
}

package main

import (
	"fmt"
	"log"
	"net/http"

	"github.com/rezmoss/axios4go"
)

func main() {
	// Define request interceptor
	requestInterceptor := func(req *http.Request) error {
		req.Header.Set("User-Agent", "axios4go-example")
		fmt.Println("Request interceptor: Added User-Agent header")
		return nil
	}

	// Define response interceptor
	responseInterceptor := func(resp *http.Response) error {
		fmt.Printf("Response interceptor: Status Code %d\n", resp.StatusCode)
		return nil
	}

	// Create a new client
	client := axios4go.NewClient("https://api.github.com")

	// Create custom transport with interceptors
	transport := &InterceptorTransport{
		Base:                http.DefaultTransport,
		RequestInterceptor:  requestInterceptor,
		ResponseInterceptor: responseInterceptor,
	}

	// Set the custom transport to the client's HTTP client
	client.HTTPClient.Transport = transport

	// Send the request
	response, err := client.Request(&axios4go.RequestOptions{})
	if err != nil {
		log.Fatalf("Request failed: %v", err)
	}

	// Print the response status and body
	fmt.Printf("Response Status: %d\n", response.StatusCode)
	fmt.Printf("Response Body: %s\n", string(response.Body))
}

// InterceptorTransport is a custom http.RoundTripper that applies interceptors
type InterceptorTransport struct {
	Base                http.RoundTripper
	RequestInterceptor  func(*http.Request) error
	ResponseInterceptor func(*http.Response) error
}

func (t *InterceptorTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// Apply request interceptor
	if t.RequestInterceptor != nil {
		if err := t.RequestInterceptor(req); err != nil {
			return nil, err
		}
	}

	// Perform the actual request
	resp, err := t.Base.RoundTrip(req)
	if err != nil {
		return nil, err
	}

	// Apply response interceptor
	if t.ResponseInterceptor != nil {
		if err := t.ResponseInterceptor(resp); err != nil {
			return nil, err
		}
	}

	return resp, nil
}
